"""Render the visual feature audit with the actual paired screenshots and videos."""
from pathlib import Path
import json,base64,html,collections,io
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'port/server/presentation-coverage.json').read_text())
OUT=ROOT/'docs/authority-parity-2026-10-29';OUT.mkdir(parents=True,exist_ok=True)
labels={'verified':'Проверено в указанном сценарии','partial':'Частично проверено','pending':'Визуально не проверено','known_gap':'Отсутствует в новой версии'}
counts=collections.Counter(f['status'] for f in DATA['features'])
def esc(s):return html.escape(str(s),quote=True)
def picture(path,label):
 p=ROOT/path
 if not p.exists():return '<p class="missing">Нет кадра: '+esc(path)+'</p>'
 buffer=io.BytesIO();im=Image.open(p).convert('RGB');im.save(buffer,format='JPEG',quality=78);data=base64.b64encode(buffer.getvalue()).decode()
 return f'<figure><figcaption>{esc(label)}</figcaption><a href="../../{esc(path)}"><img loading="lazy" alt="{esc(label)}" src="data:image/jpeg;base64,{data}"></a></figure>'
rows=[]
for f in DATA['features']:
 evidence=''
 for item in f['evidence']:
  pair=''.join(picture(item[side],name) for side,name in [('legacy','Legacy'),('server','Сервер')] if side in item)
  evidence+=f'<h4>{esc(item["label"])}</h4><div class="pair">{pair}</div>'
 if evidence:evidence='<details><summary>Кадры сравнения</summary>'+evidence+'</details>'
 rows.append(f'<tr data-state="{f["status"]}"><td><small>{esc(f["group"])}</small><strong>{esc(f["feature"])}</strong></td><td>{esc(f["legacy"])}</td><td>{esc(f["server"])}{evidence}</td><td><span class="tag {f["status"]}">{labels[f["status"]]}</span></td></tr>')
stats=''.join(f'<button data-filter="{k}" class="stat {k}"><b>{counts[k]}</b>{v}</button>' for k,v in labels.items())
films=''
for title,path in [('Legacy · 15 передач хода до новой недели','turn-final/legacy'),('Сервер · 15 передач хода до новой недели','turn-corrected/authority'),('WebKit · передача хода и reload','turn-webkit/authority'),('Legacy · город и смена дня','extended-final/legacy'),('Сервер · город и смена дня','extended-final/authority'),('Legacy · полный бой','battle-final/legacy'),('Сервер · полный бой','battle-final/authority'),('Сервер · маршрут, остановка авто, reload боя','canonical-display/authority'),('WebKit · бой и reload','webkit-battle/authority'),('Legacy · стрелки и отступление','ranged-complete/legacy'),('Сервер · стрелки','ranged/authority')]:
 films+=f'<figure><figcaption>{esc(title)}</figcaption><video controls muted playsinline preload="none" src="../../test-results/authority-parity/{path}/player-0.webm"></video></figure>'
transitions=''.join('<figure><figcaption>'+label+'</figcaption><img loading="lazy" src="data:image/jpeg;base64,'+base64.b64encode((ROOT/f'test-results/authority-parity/battle-final/authority/animation-frames/{name}-contact.jpg').read_bytes()).decode()+'"></figure>' for name,label in [('walk','Шаг героя и прокрутка'),('spell','Оригинальный эффект Haste'),('battle','Удары, Magic Arrow и потери')])
page='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HoMM3 — визуальный паритет мультиплеера</title><style>
:root{color-scheme:dark;--bg:#10151b;--panel:#1b242e;--line:#344252;--text:#e8edf3;--muted:#a8b8c9;--green:#9bd8b1;--amber:#ebca85}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:40px 28px}h1{font-size:clamp(28px,4vw,48px);line-height:1.1;margin:12px 0 20px}h2{margin-top:38px}h4{margin-bottom:8px}p{max-width:1000px}small,.muted{color:var(--muted)}a{color:#a9d2fa}strong{display:block}header{border-bottom:1px solid var(--line);padding-bottom:24px}.stats{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.stat{flex:1;min-width:160px;text-align:left;background:var(--panel);padding:16px;border:1px solid var(--line);border-radius:10px;color:var(--text);cursor:pointer;font:inherit}.stat b{display:block;font-size:34px}.verified b{color:var(--green)}.partial b{color:var(--amber)}button:focus-visible,summary:focus-visible,input:focus-visible{outline:2px solid #8bc3ff;outline-offset:3px}.filters{display:flex;gap:12px;margin:16px 0}input{width:min(500px,75%);padding:12px;background:var(--panel);border:1px solid var(--line);border-radius:6px;color:var(--text);font:inherit}.reset{background:var(--panel);color:var(--text);border:1px solid var(--line);padding:12px;border-radius:6px;cursor:pointer}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th{text-align:left;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.06em}td,th{padding:16px 12px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{width:18%}td:nth-child(2){width:23%}td:nth-child(3){width:44%}.tag{font-size:12px;display:inline-block;padding:5px 9px;border:1px solid var(--line);border-radius:5px}.tag.verified{color:var(--green)}.tag.partial{color:var(--amber)}.tag.known_gap{color:#f2ac9b}.pair,.videos,.transitions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}figure{margin:0;min-width:0;background:#080b0f;border:1px solid var(--line);border-radius:6px;overflow:hidden}figcaption{padding:10px;color:var(--muted);font-size:13px}img,video{width:100%;display:block;max-height:700px;object-fit:contain}summary{cursor:pointer;color:#a9d2fa;margin-top:12px}details[open]{margin-top:16px}.missing{color:#f2ac9b}.note{padding:18px 22px;border-left:3px solid var(--amber);background:var(--panel)}.fixes{columns:2;column-gap:40px;max-width:1200px}.fixes li{margin:0 0 10px;break-inside:avoid}[hidden]{display:none!important}@media(max-width:700px){main{padding:24px 16px}.pair,.videos,.transitions{grid-template-columns:1fr}.fixes{columns:1}td,th{padding:12px 8px}}
</style></head><body><main><header><small>29 октября 2026 · локальная сборка · без звука · прод не менялся</small><h1>Legacy ↔ сервер:<br>матрица визуального паритета</h1><p>Исправлен разрыв между серверным результатом и оригинальным интерфейсом. Герой движется, портреты и армии переходят между рядами города, бой проигрывает действия перед итоговой проекцией, заклинания отражаются в эффектах и карточках.</p><p class="note">Это проверка перечисленных сценариев, а не заявление о полном паритете всех механик Heroes III. Частично проверенные и отсутствующие возможности отмечены отдельно. Live reconnect не является сохранением партии.</p>'''+stats+'''</header><h2>Что исправлено</h2><ul class="fixes"><li>Шаг героя и камера: оригинальная анимация вместо неподвижного курсора над новыми координатами.</li><li>Вход в город: восстановление посетителя перед открытием окна.</li><li>Гарнизон/посетитель: пересоздание привязок обеих полос героя и армии.</li><li>Камера второго игрока центрируется при получении хода.</li><li>Выбранный стартовый герой действительно передаётся серверному генератору.</li><li>Бой: idle, ходьба/полёт, атаки, ответ, потери, смерть, ожидание и защита.</li><li>Заклинания: жест героя, оригинальные эффекты, значки, цвет численности, реальные модификаторы и порядок эффектов.</li><li>Автобой: стандартные combat-настройки worker, остановка и восстановление ручного управления.</li><li>Начальная боевая проекция не теряется из-за быстрого ИИ; observer frame содержит revision.</li><li>Во время воспроизведения/обрыва сети новая команда не отправляется; reload не повторяет старый журнал.</li></ul><h2>Матрица — '''+str(len(DATA['features']))+''' фич</h2><p class="muted">'''+esc(DATA['method'])+'''</p><div class="filters"><input id="search" aria-label="Найти фичу" placeholder="Поиск по фиче или замечанию"><button class="reset" id="reset">Все строки</button></div><div class="table"><table><thead><tr><th>Фича</th><th>Ожидание Legacy</th><th>Новая версия и доказательства</th><th>Статус</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><h2>Промежуточные кадры</h2><p>Кадры извлечены из реальной записи серверной игры. Здесь видны переходы, а не только совпавшие конечные координаты.</p><div class="transitions">'''+transitions+'''</div><h2>Полные записи</h2><p class="muted">Видео без звука. Разные RNG объясняют различия нейтралов и численности между независимыми партиями.</p><div class="videos">'''+films+'''</div><h2>Исправление ожидания и смены дня</h2><p>Предыдущая зелёная оценка строк «Ожидание чужого хода» и «Новый день и неделя» была преждевременной: проверялись итоговые данные, а промежуточные экраны расходились. Теперь строки содержат парные кадры обоих клиентов: текущий игрок, начало своего хода, отправка/получение и неделя. Оригинальный процент передачи save-файла не имитируется в новом протоколе. Тест недели также выявил и устранил обращение headless worker к отсутствующему окну; повторный прогон до второй недели прошёл.</p><h2>Проверки и границы</h2><p>Native: реальные бои, тактика, стрельба, полёт, осада, заклинания, отступление/сдача, bounded journal, значения для интерфейса. Worker: выбранные герои 128/137/143; 15 передач хода, новый день и уведомления недели обоим людям. JS: порядок начального состояния/выбора, границы журнала, блокировка ввода. Chromium: парные город/бой, маршрут, авто stop, reload. WebKit: полный бой, stop, reload.</p><p>Native fixtures подтверждают правила и контракт, но не заменяют визуальный тест. Ещё открыты полный браузерный PvP, весь набор заклинаний/осад/тактики, специальные рынки и отдельные операции армий/артефактов. Отдельные отсутствующие функции: долговечные server saves и оригинальный финальный экран партии.</p><p><a href="../../port/server/presentation-coverage.json">Матрица JSON</a> · <a href="../../scripts/authority-visual-parity.py">Сценарии воспроизведения</a> · <a href="../../test-results/authority-combat/results.json">Native бои</a> · <a href="../../test-results/authority-parity/setup.json">Выбор героя</a></p><script>
let state='';const q=document.querySelector('#search');function filter(){let term=q.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!!((state&&row.dataset.state!==state)||(term&&!row.textContent.toLowerCase().includes(term))))}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state=b.dataset.filter;filter()});q.oninput=filter;document.querySelector('#reset').onclick=()=>{state='';q.value='';filter()};
</script></main></body></html>'''
(OUT/'index.html').write_text(page)
print(json.dumps({'report':str(OUT/'index.html'),'features':len(rows),'statuses':dict(counts),'bytes':len(page.encode())},ensure_ascii=False))
